// SPDX-License-Identifier: Apache-2.0
//
// Run state machine (ADR 0030). Every transition is a compare-and-set on the
// source state, and owner writes also on the epoch: a racing, illegal or stale
// write matches no rows (pgx.ErrNoRows for :one). The runs_check_transition
// trigger rejects anything else.
//
// Every query on an org-owned table takes @org_id and filters on it
// (TestQueriesAreOrgScoped).
// Queues a run of the agent's approved version. No row: the agent is not
// active.
// origin is interactive unless the caller says scheduled (LT1: interactive work is claimed first).
func (q *Queries) CreateRun(ctx context.Context, arg CreateRunParams) (Run, error) {
	row := q.db.QueryRow(ctx, createRun,
		arg.TaskID,
		arg.MaxWallClockSeconds,
		arg.MaxModelRequests,
		arg.MaxSpendUsd,
		arg.Origin,
		arg.OrgID,
		arg.AgentID,
	)
	var i Run
	err := row.Scan(
		&i.OrgID,
		&i.ID,
		&i.AgentID,
		&i.AgentVersionID,
		&i.TaskID,
		&i.State,
		&i.Epoch,
		&i.OwnerID,
		&i.LeaseExpiresAt,
		&i.HeartbeatAt,
		&i.ReadyAt,
		&i.ParkReason,
		&i.ParkedAt,
		&i.ParkExpiresAt,
		&i.OutcomeReason,
		&i.MaxWallClockSeconds,
		&i.MaxTokens,
		&i.LastEventSeq,
		&i.StartedAt,
		&i.FinishedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ParkedSeconds,
		&i.TokensUsed,
		&i.PromptThroughSeq,
		&i.Takeovers,
		&i.Summarizing,
		&i.FailureClass,
		&i.Origin,
		&i.ClaimedAt,
		&i.SandboxWaitStartedAt,
		&i.WrapUpNoticeAt,
		&i.MaxModelRequests,
		&i.MaxSpendUsd,
		&i.Traced,
		&i.LastTurnSeq,
		&i.ContentPurgedAt,
	)
	return i, err
}

