const takeOverExpiredRun = `-- name: TakeOverExpiredRun :one
WITH stale AS (
    SELECT r.id AS run_id, r.agent_id
    FROM runs r
    WHERE r.org_id = $3
      AND r.state IN ('starting', 'running')
      AND r.lease_expires_at < now()
    ORDER BY r.lease_expires_at, r.id
    LIMIT 1
    FOR UPDATE SKIP LOCKED
), agent AS (
    UPDATE agents
    SET epoch = agents.epoch + 1
    FROM stale
    WHERE agents.org_id = $3 AND agents.id = stale.agent_id
    RETURNING agents.id, agents.epoch
)
UPDATE runs
SET epoch = agent.epoch,
    summarizing = false,
    takeovers = runs.takeovers + 1,
    owner_id = $1::text,
    -- A starting run's claim time is when this owner began waiting for the sandbox, so a later
    -- requeue does not credit the dead owner's lease time to parked_seconds.
    claimed_at = CASE WHEN runs.state = 'starting' THEN now() ELSE runs.claimed_at END,
    lease_expires_at = now() + make_interval(secs => $2::integer),
    heartbeat_at = now()
FROM stale
JOIN agent ON agent.id = stale.agent_id
WHERE runs.org_id = $3 AND runs.id = stale.run_id
RETURNING runs.org_id, runs.id, runs.agent_id, runs.agent_version_id, runs.task_id, runs.state, runs.epoch, runs.owner_id, runs.lease_expires_at, runs.heartbeat_at, runs.ready_at, runs.park_reason, runs.parked_at, runs.park_expires_at, runs.outcome_reason, runs.max_wall_clock_seconds, runs.max_tokens, runs.last_event_seq, runs.started_at, runs.finished_at, runs.created_at, runs.updated_at, runs.parked_seconds, runs.tokens_used, runs.prompt_through_seq, runs.takeovers, runs.summarizing, runs.failure_class, runs.origin, runs.claimed_at, runs.sandbox_wait_started_at, runs.wrap_up_notice_at, runs.max_model_requests, runs.max_spend_usd, runs.traced, runs.last_turn_seq, runs.content_purged_at
`

